mapper.select:
SELECT (CASE WHEN pra.REPORT_STATUS is null THEN #{dataStatus_wait} ELSE pr.DATA_STATUS end) dataStatus, pra.REPORT_STATUS reportStatus, pra.REPORT_DECR reportDecr, pr.REQUIREMENT_ID requirementId, pr.REQUIREMENT_USER requirementUser, pr.REVIEW_YESNO reviewYesno, pr.REQUIREMENT_BASIS requirementBasis, pr.REQUIREMENT_DATE requirementTime, pr.TAR_CUSTOMER tarCustomer, pr.PRD_SCALE prdScale, pr.PRD_PERIOD prdPeriod, pr.PRD_RATE prdRate, pr.PRD_REQUIREMENT_DETIAL prdRequirementDetail, pr.REQUIREMENT_SOURCE requirementSource FROM PRODUCT_REQUIREMENT pr LEFT JOIN PRODUCT_REQUIREMENT_ADD pra ON pr.REQUIREMENT_ID = pra.REQUIREMENT_ID WHERE pr.DATA_STATUS = #{dataStatus_effective} AND pr.REVIEW_YESNO = #{reviewYesno_yes}
AND pra.REPORT_STATUS is null
AND pra.REPORT_STATUS is not null
AND pr.REQUIREMENT_SOURCE = #{requirementSource}
and pr.REQUIREMENT_DATE >= STR_TO_DATE(#{requirementTimeStart}, '%Y-%m-%d')
and pr.REQUIREMENT_DATE <= STR_TO_DATE(#{requirementTimeEnd}, '%Y-%m-%d')
AND pr.TAR_CUSTOMER like concat('%',#{tarCustomer},'%')
AND pra.REPORT_STATUS = #{reportStatus}
